<?php require_once __DIR__.'/../includes/auth.php'; require_role(['student']); $pageTitle='Dashboard'; require __DIR__.'/../includes/header.php'; $u=current_user();$s=$pdo->prepare('SELECT COUNT(*) FROM item_reports WHERE user_id=?');$s->execute([$u['id']]);$reports=(int)$s->fetchColumn();$s=$pdo->prepare('SELECT COUNT(*) FROM claim_requests WHERE claimant_id=?');$s->execute([$u['id']]);$claims=(int)$s->fetchColumn();echo '<section class="welcome"><p class="eyebrow">STUDENT DASHBOARD</p><h1>Hi, '.e($u['full_name']).' 👋</h1><p>Manage your reports and follow your claims here.</p></section><div class="stats"><div class="stat"><span>My reports</span><strong>'.$reports.'</strong></div><div class="stat"><span>My claims</span><strong>'.$claims.'</strong></div></div><div class="actions"><a class="btn primary" href="'.e(url('student/report-item.php')).'">Report item</a><a class="btn secondary" href="'.e(url('student/browse-items.php')).'">Browse items</a><a class="btn secondary" href="'.e(url('student/my-reports.php')).'">My reports</a><a class="btn secondary" href="'.e(url('student/my-claims.php')).'">My claims</a></div>'; require __DIR__.'/../includes/footer.php'; ?>